js='''\nconst SUPABASE_URL='https://gdycbluljgfezhgslppe.supabase.co';\nconst SUPABASE_KEY='sb_publishable_ke21EcVtLjGPLwX2T_-xng_CnhM6HBM';\nconst sb=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);\nlet communityUser=null,communityRooms=[],activeRoom=null,chatChannel=null;\nasync function initCommunity(){\n  try{let {data:{session}}=await sb.auth.getSession();communityUser=session?.user||null;await loadCommunityRooms();applyMemberState();if(activeRoom)await loadCommunityMessages();sb.auth.onAuthStateChange(async(_e,session)=>{communityUser=session?.user||null;applyMemberState();if(activeRoom)await loadCommunityMessages()})}catch(e){txt('communityAuthStatus','Community connection unavailable.')}\n}\nasync function communitySignUp(btn){let email=$('memberEmail')?.value.trim(),password=$('memberPassword')?.value||'',name=$('memberName')?.value.trim();if(!email||password.length<6||!name)return txt('communityAuthStatus','Enter display name, valid email and password of at least 6 characters.');setBusy(btn,true);let {data,error}=await sb.auth.signUp({email,password,options:{data:{display_name:name}}});setBusy(btn,false);if(error)return txt('communityAuthStatus',error.message);txt('communityAuthStatus',data.session?'Account created and signed in.':'Account created. Check your email if confirmation is required.')}\nasync function communitySignIn(btn){let email=$('memberEmail')?.value.trim(),password=$('memberPassword')?.value||'';if(!email||!password)return txt('communityAuthStatus','Enter your email and password.');setBusy(btn,true);let {error}=await sb.auth.signInWithPassword({email,password});setBusy(btn,false);txt('communityAuthStatus',error?error.message:'Signed in successfully.')}\nasync function communitySignOut(){await sb.auth.signOut();communityUser=null;applyMemberState()}\nfunction applyMemberState(){let signed=!!communityUser;$('communityAuthCard').style.display=signed?'none':'block';$('communityComposer').style.display=signed?'flex':'none';$('signOutBtn').style.display=signed?'inline-block':'none';$('communityGuestHint').style.display=signed?'none':'block';let name=communityUser?.user_metadata?.display_name||communityUser?.email||'Member';txt('memberState',signed?'Signed in as '+name:'Guest mode')}\nasync function loadCommunityRooms(){let {data,error}=await sb.from('community_rooms').select('id,slug,name,description').order('created_at');if(error){txt('chatList','Could not load community rooms.');return}communityRooms=data||[];if(!activeRoom&&communityRooms.length)activeRoom=communityRooms[0].id;renderCommunityRooms()}\nfunction renderCommunityRooms(){let el=$('communityRooms');if(!el)return;el.innerHTML=communityRooms.map(r=>`<button class="roomBtn ${r.id===activeRoom?'active':''}" onclick="selectCommunityRoom('${r.id}')">${esc(r.name)}</button>`).join('')}\nasync function selectCommunityRoom(id){activeRoom=id;renderCommunityRooms();await loadCommunityMessages()}\nasync function loadCommunityMessages(){if(!activeRoom)return;let {data,error}=await sb.from('community_messages').select('id,message,created_at,user_id,profiles(display_name)').eq('room_id',activeRoom).order('created_at',{ascending:false}).limit(60);if(error){$('chatList').innerHTML='<div class="sub">Could not load messages.</div>';return}renderCommunityMessages((data||[]).reverse());subscribeCommunity()}\nfunction renderCommunityMessages(items){let el=$('chatList');if(!el)return;if(!items.length){el.innerHTML='<div class="sub">No messages yet. Be the first commuter to say hello 👋</div>';return}el.innerHTML=items.map(m=>{let n=m.profiles?.display_name||'Commuter',d=new Date(m.created_at).toLocaleString('en-SG',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});return `<div class="chatMsg"><div class="chatMeta"><span class="chatName">${esc(n)}</span><span>${esc(d)}</span></div><div>${esc(m.message)}</div></div>`}).join('');el.scrollTop=el.scrollHeight}\nfunction subscribeCommunity(){if(chatChannel){sb.removeChannel(chatChannel);chatChannel=null}if(!activeRoom)return;chatChannel=sb.channel('community-'+activeRoom).on('postgres_changes',{event:'*',schema:'public',table:'community_messages',filter:'room_id=eq.'+activeRoom},()=>loadCommunityMessages()).subscribe()}\nasync function sendCommunityMessage(btn){if(!communityUser)return txt('communityGuestHint','Please sign in before posting.');let message=$('chatMessage')?.value.trim();if(!message||!activeRoom)return;setBusy(btn,true);let {error}=await sb.from('community_messages').insert({room_id:activeRoom,user_id:communityUser.id,message});setBusy(btn,false);if(error){alert(error.message);return}$('chatMessage').value='';await loadCommunityMessages()}\n'''
